<script setup lang="ts">import {dateTime} from '@/lib/format';defineProps<{count:number;hasNext?:boolean;hasPrevious?:boolean;loading?:boolean;snapshot?:string}>();defineEmits(['next','previous','refresh'])</script>
<template><div class="pager"><span class="muted">本批 {{count}} 条<span v-if="snapshot"> · {{dateTime(snapshot)}}</span></span><div><el-button :disabled="loading||!hasPrevious" @click="$emit('previous')">上一批</el-button><el-button :disabled="loading||!hasNext" @click="$emit('next')">下一批</el-button><el-button :disabled="loading" @click="$emit('refresh')">刷新</el-button></div></div></template>
